package org.joda.time;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.joda.convert.FromString;
import org.joda.time.base.BasePeriod;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.ISOPeriodFormat;
import org.joda.time.format.PeriodFormatter;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Period_normalizedStandard_TriageGen0Test {

    @Test
    public void testNormalizedStandard_WithFullPeriodType() {
        // Test with all fields supported
        Period period = new Period(1, 2, 3, 4, 5, 6, 7, 8);
        PeriodType type = PeriodType.full();
        Period result = period.normalizedStandard(type);

        assertEquals(1, result.getYears());
        assertEquals(2, result.getMonths());
        assertEquals(3, result.getWeeks());
        assertEquals(4, result.getDays());
        assertEquals(5, result.getHours());
        assertEquals(6, result.getMinutes());
        assertEquals(7, result.getSeconds());
        assertEquals(8, result.getMillis());
        assertEquals(type, result.getPeriodType());
    }

    @Test
    public void testNormalizedStandard_WithNoYearsOrMonths() {
        // Test case where years and months are 0 (skips the normalization logic block)
        Period period = new Period(0, 0, 1, 2, 3, 4, 5, 6);
        PeriodType type = PeriodType.dayAndTime();
        Period result = period.normalizedStandard(type);

        assertEquals(0, result.getYears());
        assertEquals(0, result.getMonths());
        assertEquals(1, result.getWeeks());
        assertEquals(2, result.getDays());
        assertEquals(3, result.getHours());
        assertEquals(4, result.getMinutes());
        assertEquals(5, result.getSeconds());
        assertEquals(6, result.getMillis());
    }

    @Test
    public void testNormalizedStandard_NormalizeToYearsAndMonths() {
        // 1 year and 2 months should be preserved if type supports years and months
        Period period = new Period(1, 2, 0, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.yearMonth();
        Period result = period.normalizedStandard(type);

        assertEquals(1, result.getYears());
        assertEquals(2, result.getMonths());
        assertEquals(0, result.getWeeks());
    }

    @Test
    public void testNormalizedStandard_NormalizeToMonthsOnly() {
        // 1 year and 2 months -> 14 months if type is months only
        Period period = new Period(1, 2, 0, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.monthTime(); 
        // Note: MonthTime supports months but not years

        Period result = period.normalizedStandard(type);

        assertEquals(0, result.getYears());
        assertEquals(14, result.getMonths());
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testNormalizedStandard_ThrowsExceptionWhenNormalizationImpossible() {
        // Period has years/months, but type doesn't support years OR months, 
        // and totalMonths calculation results in a remainder that can't be placed.
        // Example: 1 year, 2 months = 14 months. 
        // If type only supports Days, the code calculates totalMonths = 14.
        // Since type.isSupported(YEARS) and MONTHS are false, totalMonths remains 14.
        // The final check 'if (totalMonths != 0)' will trigger the exception.

        Period period = new Period(1, 2, 0, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.dayTime(); 

        period.normalizedStandard(type);
    }

    @Test
    public void testNormalizedStandard_WithZeroYearsAndMonthsExplicitly() {
        // Test boundary where years/months are 0 but logic enters the block if years/months are set
        Period period = new Period(0, 0, 0, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.standard();
        Period result = period.normalizedStandard(type);

        assertEquals(0, result.getYears());
        assertEquals(0, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_LargeValues() {
        // Test for potential overflow handling in millis calculation
        // getMillis() is long, so we test with large components
        Period period = new Period(0, 0, 0, 1000, 1000, 1000, 1000, 1000);
        PeriodType type = PeriodType.standard();
        Period result = period.normalizedStandard(type);

        assertNotNull(result);
        assertTrue(result.getMillis() > 0);
    }

    @Test
    public void testNormalizedStandard_NegativeValues() {
        // Test with negative periods
        Period period = new Period(-1, -2, 0, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.yearMonth();
        Period result = period.normalizedStandard(type);

        assertEquals(-1, result.getYears());
        assertEquals(-2, result.getMonths());
    }
}
